"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["32264"],{22420(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.conferencia_endereco_geo.municipio_divergente","status":422,"titulo":"O munic\xedpio informado n\xe3o pertence \xe0 UF declarada"},"descricao":{"codigo":"uniplus.selecao.conferencia_endereco_geo.municipio_divergente","requisitos":["UNI-REQ-0214"],"oQueAconteceu":["No envio da inscri\xe7\xe3o, o sistema confere no Geo, o cadastro de localidades\\ndo Uni+, que o munic\xedpio informado existe e pertence \xe0 UF que o candidato\\ndeclarou no campo de UF correspondente. Por exemplo, Erick Isaac Ramos\\nnasceu em Salvador, que \xe9 da Bahia; se o formul\xe1rio traz \\"PA\\" como UF de\\nnascimento e o c\xf3digo de Salvador como munic\xedpio, o munic\xedpio n\xe3o pertence\\n\xe0 UF declarada.","A recusa vem uma s\xf3 vez no campo do munic\xedpio, e n\xe3o se repete com a\\nmensagem gen\xe9rica de munic\xedpio fora da UF. Quando o munic\xedpio est\xe1 dentro\\nde um grupo repet\xedvel, ela vem no item daquela ocorr\xeancia."],"comoResolver":["Confira os dois campos juntos: a UF e o munic\xedpio. Escolha primeiro a UF\\ncorreta e, em seguida, o munic\xedpio na lista, que vem do Geo e mostra s\xf3 os\\nmunic\xedpios daquela UF. Se o erro estava na UF, corrija a UF e escolha o\\nmunic\xedpio de novo. Depois envie a inscri\xe7\xe3o outra vez. Nada desta tentativa foi gravado."],"ondeAparece":["Envio da inscri\xe7\xe3o do candidato"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Conferencia endereco geo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);